attributes._cssText:
body { font: 15px system-ui, sans-serif; margin: 0px; background: rgb(246, 247, 249); color: rgb(29, 35, 48); }header { background: rgb(29, 35, 48); color: rgb(255, 255, 255); padding: 12px 24px; display: flex; gap: 24px; align-items: center; }header b { font-size: 16px; }header a { color: rgb(201, 209, 224); text-decoration: none; }main { padding: 28px 32px; max-width: 880px; }h1 { font-size: 22px; margin: 0px 0px 18px; }label { display: block; margin: 12px 0px 4px; font-weight: 600; }input[type="text"], input:not([type]) { font: inherit; padding: 8px 10px; border: 1px solid rgb(197, 204, 216); border-radius: 6px; width: 320px; }button { font: inherit; padding: 8px 16px; border-radius: 6px; border: 1px solid rgb(47, 91, 211); background: rgb(47, 91, 211); color: rgb(255, 255, 255); cursor: pointer; margin-top: 14px; }.err { color: rgb(198, 40, 40); margin-top: 8px; }.ok { color: rgb(27, 127, 59); margin-top: 8px; }table { border-collapse: collapse; background: rgb(255, 255, 255); width: 100%; table-layout: fixed; }td, th { border-bottom: 1px solid rgb(227, 231, 238); padding: 10px; text-align: left; }.spinner { width: 28px; height: 28px; border-width: 3px; border-style: solid; border-color: rgb(47, 91, 211) rgb(197, 204, 216) rgb(197, 204, 216); border-image: none; border-radius: 50%; animation: 1s linear 0s infinite normal none running spin; margin: 24px 0px; }@keyframes spin { 
  100% { transform: rotate(360deg); }
}

